import React, { useState, useEffect } from 'react';
import { useAuth } from '../AuthContext';
import IncidentReportingModal from './IncidentReportingModal';

function IncidentReportingDashboard() {
  const { authFetch, currentUser } = useAuth();
  const [incidents, setIncidents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedIncident, setSelectedIncident] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [incidentToEdit, setIncidentToEdit] = useState(null);
  const [isReadOnly, setIsReadOnly] = useState(false);
  const [filter, setFilter] = useState('all');

  const handleOpenForm = () => {
    setIncidentToEdit(null);
    setIsReadOnly(false);
    setIsModalOpen(true);
  };

  const handleEditIncident = () => {
    setIncidentToEdit(selectedIncident);
    setIsReadOnly(false);
    setIsModalOpen(true);
  };

  const handleViewIncident = () => {
    setIncidentToEdit(selectedIncident);
    setIsReadOnly(true);
    setIsModalOpen(true);
  };

  const fetchIncidents = async () => {
    setLoading(true);
    try {
      const res = await authFetch('/api/v1/incidents');
      if (!res.ok) throw new Error('Failed to fetch incidents');
      const data = await res.json();
      setIncidents(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchIncidents();
  }, [authFetch]);

  const filteredIncidents = incidents.filter(s => {
    if (filter === 'all') return true;
    return s.status === filter;
  });

  const handleStatusChange = async (incidentId, newStatus) => {
    try {
      const res = await authFetch(`/api/v1/incidents/${incidentId}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus })
      });
      if (res.ok) {
        fetchIncidents();
        if (selectedIncident && selectedIncident.id === incidentId) {
          setSelectedIncident(prev => ({ ...prev, status: newStatus }));
        }
      } else {
        console.error("Failed to update status");
      }
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="main-content" style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>

      {/* Left Panel: Feed */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', borderRight: '1px solid var(--border-color)', backgroundColor: 'var(--bg-panel)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '15px 25px', borderBottom: '1px solid var(--border-color)' }}>
          <div style={{ fontWeight: '600', fontSize: '18px' }}>Incident Reporting</div>
          <div style={{ display: 'flex', gap: '10px' }}>
            <select 
              value={filter} 
              onChange={(e) => setFilter(e.target.value)}
              className="field-input"
              style={{ padding: '5px', fontSize: '13px', width: '150px' }}
            >
              <option value="all">All Statuses</option>
              <option value="Open">Open</option>
              <option value="Investigating">Investigating</option>
              <option value="Closed">Closed</option>
            </select>
            <button className="submit-btn" style={{ padding: '8px 16px' }} onClick={handleOpenForm}>
              + Report Incident
            </button>
          </div>
        </div>

        <div style={{ overflowY: 'auto', flex: 1 }}>
          {loading ? (
            <div style={{ padding: '20px' }}>Loading reports...</div>
          ) : filteredIncidents.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '40px', color: 'var(--text-dim)' }}>No incident reports found.</div>
          ) : (
            <table className="intel-table" style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '14px' }}>
              <thead>
                <tr style={{ borderBottom: '1px solid var(--border-color)', backgroundColor: 'var(--bg-glass)' }}>
                  <th style={{ padding: '10px 15px' }}>Case ID</th>
                  <th style={{ padding: '10px 15px' }}>State</th>
                  <th style={{ padding: '10px 15px' }}>Status</th>
                  <th style={{ padding: '10px 15px' }}>Title</th>
                  <th style={{ padding: '10px 15px' }}>Date (Local)</th>
                  <th style={{ padding: '10px 15px' }}>Organization</th>
                </tr>
              </thead>
              <tbody>
                {filteredIncidents.map(inc => (
                  <tr 
                    key={inc.id}
                    onClick={() => { setSelectedIncident(inc); }}
                    style={{ 
                      borderBottom: '1px solid var(--border-color)', 
                      cursor: 'pointer',
                      backgroundColor: selectedIncident?.id === inc.id ? 'var(--bg-glass)' : 'transparent',
                    }}
                    onMouseEnter={(e) => { if (selectedIncident?.id !== inc.id) e.currentTarget.style.backgroundColor = 'rgba(255,255,255,0.02)'; }}
                    onMouseLeave={(e) => { if (selectedIncident?.id !== inc.id) e.currentTarget.style.backgroundColor = 'transparent'; }}
                  >
                    <td style={{ padding: '10px 15px', color: 'var(--accent)', fontWeight: 'bold' }}>{inc.case_id}</td>
                    <td style={{ padding: '10px 15px' }}>
                      <span style={{ fontSize: '11px', padding: '2px 8px', borderRadius: '10px', background: 'rgba(255,255,255,0.1)' }}>
                        {inc.is_draft ? 'Draft' : (inc.form_data?.reportType === 'Update to Previously Reported Incident' ? 'Updated' : 'Submitted')}
                      </span>
                    </td>
                    <td style={{ padding: '10px 15px' }}>
                      <span style={{ fontSize: '11px', padding: '2px 8px', borderRadius: '10px', background: 'rgba(255,255,255,0.1)' }}>
                        {inc.status}
                      </span>
                    </td>
                    <td style={{ padding: '10px 15px', fontWeight: 'bold' }}>{inc.title || 'Untitled Incident'}</td>
                    <td style={{ padding: '10px 15px', color: 'var(--text-dim)', fontSize: '13px' }}>{new Date(inc.created_at).toLocaleString()}</td>
                    <td style={{ padding: '10px 15px', color: 'var(--text-dim)', fontSize: '13px' }}>{inc.organization?.name}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* Right Panel: Detail View */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', backgroundColor: 'var(--bg-panel)', overflowY: 'auto' }}>
        {selectedIncident ? (
          <div style={{ padding: '25px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
              <div>
                <div style={{ fontSize: '13px', color: 'var(--accent)', fontWeight: 'bold', marginBottom: '5px' }}>
                  {selectedIncident.case_id} • {selectedIncident.is_draft ? '(Draft)' : ''}

                  {currentUser?.organization?.org_type === 'ACSAC' ? (
                    <select
                      value={selectedIncident.status}
                      onChange={(e) => handleStatusChange(selectedIncident.id, e.target.value)}
                      style={{ marginLeft: '10px', background: 'transparent', color: 'inherit', border: '1px solid var(--border-color)', borderRadius: '4px', padding: '2px 5px' }}
                    >
                      <option value="Open" style={{ color: 'black' }}>Open</option>
                      <option value="Investigating" style={{ color: 'black' }}>Investigating</option>
                      <option value="Closed" style={{ color: 'black' }}>Closed</option>
                    </select>
                  ) : (
                    ` • ${selectedIncident.status}`
                  )}
                </div>
                <h2 style={{ margin: '0 0 10px 0' }}>{selectedIncident.title || 'Untitled Incident'}</h2>
                <div style={{ fontSize: '13px', color: 'var(--text-dim)' }}>Reported by <strong>{selectedIncident.organization?.name}</strong> • Occurred on: {new Date(selectedIncident.incident_date).toLocaleString()}</div>
              </div>
              <div style={{ display: 'flex', gap: '10px' }}>
                {currentUser?.organization?.org_type === 'ACSAC' ? (
                  <button className="submit-btn" style={{ padding: '8px 16px', background: 'transparent', border: '1px solid var(--accent)', color: 'var(--accent)' }} onClick={handleViewIncident}>
                    View Form Data
                  </button>
                ) : (
                  <button className="submit-btn" style={{ padding: '8px 16px', background: 'transparent', border: '1px solid var(--accent)', color: 'var(--accent)' }} onClick={handleEditIncident}>
                    Edit Incident
                  </button>
                )}
              </div>
            </div>

            <div style={{ background: 'var(--bg-glass)', padding: '20px', borderRadius: '8px', border: '1px solid var(--border-color)' }}>
              <h4 style={{ margin: '0 0 10px 0' }}>Description</h4>
              <p style={{ whiteSpace: 'pre-wrap', margin: 0, fontSize: '14px', lineHeight: '1.6' }}>
                {selectedIncident.description === 'See form data' ? 'Refer to the full form data for details.' : selectedIncident.description}
              </p>
            </div>

            {/* Removed the raw JSON dump as we now have a View Form Data button */}

            {selectedIncident.attachments && selectedIncident.attachments.length > 0 && (
              <div style={{ background: 'var(--bg-glass)', padding: '20px', borderRadius: '8px', border: '1px solid var(--border-color)' }}>
                <h4 style={{ margin: '0 0 10px 0' }}>Attachments</h4>
                <ul style={{ margin: 0, paddingLeft: '20px', fontSize: '14px' }}>
                  {selectedIncident.attachments.map((att, idx) => (
                    <li key={idx}>
                      <a href={`/api/v1/incidents/${selectedIncident.id}/attachment/${att.filename}`} target="_blank" rel="noreferrer" style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                        {att.filename}
                      </a>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        ) : (
          <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', flexDirection: 'column', color: 'var(--text-dim)' }}>
            <div style={{ fontSize: '40px', marginBottom: '20px' }}>🚨</div>
            <h3>Incident Reporting</h3>
            <p>Select a report on the left to view details, or report a new incident.</p>
          </div>
        )}
      </div>

      <IncidentReportingModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSuccess={() => {
          setIsModalOpen(false);
          fetchIncidents();
        }}
        existingIncident={incidentToEdit}
        readOnly={isReadOnly}
      />
    </div>
  );
}

export default IncidentReportingDashboard;
